ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
(vars.metadata map((item,index)->
	{
		"draw": item."drawExternalIDLanded",
		"LITM": item.IBLITM
	}
) distinctBy $.draw) filter (!isEmpty($.draw))

%dw 2.0
output application/json
---
(vars.metadata map((item,index)->
	{
		"srtx": item."srtxExternalIDLanded",
		"LITM": item.IBLITM
	}
) distinctBy $."srtx") filter (!isEmpty($."srtx"))

email:body.email:content:
#[%dw 2.0
	output application/xml
	skipNullOn="everywhere"

	---
	{
		"html":{
			"body":{
				"div" @(class:"total"):{
					"div" @(class:"header"):{
						"h2":"Status Update from Mulesoft"
					},
					"div" @(class:"content"):{
						"p": "Hi,",
						"p": "Greetings!!!",
						"p": vars.status
					},

					"div":{
						"table" @(width:'40%', border:'1', cellspacing:'0'): {
								"tr":{
									"th": "InterfaceName",
									"td": p('app.name')
								},
						 (payload map (item) -> {
									  tr: {
										th: "Status",
										td: "Failure"
									  }
									})                 

							}
					}
				}
			}
		}
	}]

logger.message:
#[%dw 2.0
output application/json
---
if (payload.successful == true) {Successful : payload.successful}
else (payload.items map() -> {
	"MessageSender": "landed-min-max-base-part-upsert",
	failedId: $.exception.message,
	message: $.message,
	Successful: $.successful	
})]

email:body.email:content:
#[%dw 2.0
output application/xml
skipNullOn="everywhere"

---
{
    "html":{
        "body":{
            "div" @(class:"total"):{
                "div" @(class:"header"):{
                    "h2":"Alert from Mulesoft"
                },
                "div" @(class:"content"):{
                    "p": "Hi,",
                    "p": "Greetings!!!",
					"p": "Error while processing, please take corrective action."
                },

                "div":{
                    "table" @(width:'40%', border:'1', cellspacing:'0'): {
							"tr":{
                                "th": "InterfaceName",
                                "td": p('app.name')
                            },
                          "tr":{
                                "th": "Error Type",
                                "td":  "Batch Processing Error while updating Landed MIN and MAX BASE Parts"
                            },
                          "tr":{
                                "th": "Failed Payload",
                                "td": payload
                            }                        

                        }
                }
            }
        }
    }
}]

logger.message:
#[%dw 2.0
output application/json
---
if (payload.successful == true) {Successful : payload.successful}
else (payload.items map() -> {
	"MessageSender": "landed-min-max-base-industry-upsert",
	failedId: $.exception.message,
	message: $.message,
	Successful: $.successful	
})]

